// קריאת המפתח מה‑environment – במקומות שבהם אפשר להשתמש ב‑dotenv (לדוגמה Node.js)
// כאן נשתמש במשתנה גלובלי שנקבע לפני הרצת הקוד (לדוגמה על ידי bundler או server)
const API_KEY = window.TOGETHER_API_KEY; // <‑ תגדיר לפני טעינת הקוד

const chatDiv = document.getElementById('chat');
const form = document.getElementById('promptForm');
const input = document.getElementById('prompt');

function addMessage(text, from) {
 const div = document.createElement('div');
 div.className = `message ${from}`;
 div.textContent = text;
 chatDiv.appendChild(div);
 chatDiv.scrollTop = chatDiv.scrollHeight;
}

async function callTogether(prompt) {
 const response = await fetch('https://api.together.xyz/v1/chat/completions', {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'Authorization': `Bearer ${API_KEY}`
 },
 body: JSON.stringify({
 model: 'meta-llama/Llama-2-70b-chat-hf', // לדוגמה, אפשר להחליף במודל הרצוי
 messages: [{ role: 'user', content: prompt }],
 max_tokens: 512,
 temperature: 0.7
 })
 });

 if (!response.ok) {
 const err = await response.text();
 throw new Error(`API error: ${response.status} – ${err}`);
 }

 const data = await response.json();
 const reply = data.choices?.[0]?.message?.content?.trim() || '...';
 return reply;
}

form.addEventListener('submit', async (e) => {
 e.preventDefault();
 const userPrompt = input.value.trim();
 if (!userPrompt) return;

 addMessage(userPrompt, 'user');
 input.value = '';
 addMessage('מחכה לתשובה…', 'ai');

 try {
 const answer = await callTogether(userPrompt);
 // מחליפים את הודעת ההמתנה בתשובה האמיתית
 const waiting = chatDiv.querySelector('.ai:last-child');
 waiting.textContent = answer;
 waiting.classList.remove('ai');
 waiting.classList.add('ai');
 } catch (err) {
 const waiting = chatDiv.querySelector('.ai:last-child');
 waiting.textContent = `שגיאה: ${err.message}`;
 }
});
