 <div id="score">נקודות: 0</div>
 <canvas id="gameCanvas" width="400" height="400"></canvas>

 <script>
 const canvas = document.getElementById('gameCanvas');
 const ctx = canvas.getContext('2d');
 const gridSize = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--grid-size'));
 const rows = canvas.height / gridSize;
 const cols = canvas.width / gridSize;

 let snake = [{x: 5, y: 5}];
 let direction = {x: 1, y: 0};
 let food = randomFood();
 let score = 0;
 let gameInterval;

 function drawCell(x, y, color) {
 ctx.fillStyle = color;
 ctx.fillRect(x * gridSize, y * gridSize, gridSize - 1, gridSize - 1);
 }

 function randomFood() {
 let position;
 do {
 position = {
 x: Math.floor(Math.random() * cols),
 y: Math.floor(Math.random() * rows)
 };
 } while (snake.some(seg => seg.x === position.x && seg.y === position.y));
 return position;
 }

 function update() {
 const head = {x: snake[0].x + direction.x, y: snake[0].y + direction.y};

 // בדיקת גבולות
 if (head.x < 0 || head.x >= cols || head.y < 0 || head.y >= rows ||
 snake.some(seg => seg.x === head.x && seg.y === head.y)) {
 clearInterval(gameInterval);
 alert('המשחק נגמר! ניקוד: ' + score);
 return;
 }

 snake.unshift(head);

 // אכילת אוכל
 if (head.x === food.x && head.y === food.y) {
 score++;
 document.getElementById('score').textContent = 'נקודות: ' + score;
 food = randomFood();
 } else {
 snake.pop(); // מחיקת הזנב אם לא אכל
 }

 render();
 }

 function render() {
 ctx.clearRect(0, 0, canvas.width, canvas.height);
 // ציור אוכל
 drawCell(food.x, food.y, getComputedStyle(document.documentElement).getPropertyValue('--food-color'));
 // ציור נחש
 snake.forEach((seg, idx) => {
 drawCell(seg.x, seg.y, getComputedStyle(document.documentElement).getPropertyValue('--snake-color'));
 });
 }

 function changeDirection(e) {
 const key = e.key;
 const map = {
 ArrowUp: {x: 0, y: -1},
 ArrowDown: {x: 0, y: 1},
 ArrowLeft: {x: -1, y: 0},
 ArrowRight: {x: 1, y: 0},
 w: {x:0, y:-1},
 s: {x:0, y:1},
 a: {x:-1, y:0},
 d: {x:1, y:0}
 };
 if (!map[key]) return;
 const newDir = map[key];
 // מניעת הפיכת כיוון 180°
 if (newDir.x === -direction.x && newDir.y === -direction.y) return;
 direction = newDir;
 }

 // התחלת המשחק
 function start() {
 document.addEventListener('keydown', changeDirection);
 gameInterval = setInterval(update, 120);
 }

 start();
